mapper.select:
SELECT id FROM episodes
WHERE drama_id = #{dramaId} AND episode_number = #{number} AND id <> #{id}
LIMIT 1

mapper.sql:
WHERE drama_id = #{dramaId}

  AND status = #{status}


  AND (title LIKE CONCAT('%', #{q}, '%') OR episode_number = #{number})

mapper.select:
SELECT * FROM episodes

ORDER BY episode_number
LIMIT #{limit} OFFSET #{offset}
